const results = $input.first()?.json.results || [];
const inputData = $('Execute Workflow Trigger').first()?.json || {};
const locale = inputData.locale || 'ar';
const isAr = locale === 'ar';

const statusMapAr = {
  'shipped': 'تم الشحن والإرسال',
  'delivered': 'تم التسليم بنجاح',
  'processing': 'قيد المعالجة والتجهيز',
  'in_review': 'قيد المراجعة والتدقيق',
  'approved': 'تمت الموافقة المبدئية',
  'cancelled': 'ملغي'
};

if (results.length > 0 && results[0].order_number) {
  const order = results[0];
  const formattedDate = order.estimated_delivery ? new Date(order.estimated_delivery).toLocaleDateString(isAr ? 'ar-SA' : 'en-US', { month: 'short', day: 'numeric', year: 'numeric' }) : (isAr ? 'قريباً' : 'soon');
  const statusText = isAr ? (statusMapAr[(order.status || '').toLowerCase()] || order.status) : (order.status || '').toUpperCase();

  let reply = '';
  if (isAr) {
    reply = `أهلاً بك ${order.full_name || 'عزيزنا العميل'}،\nحالة طلبك/طلب الخدمة رقم **${order.order_number}** هي: **${statusText}**.\n\n`;
    if (order.carrier && order.tracking_number) {
      reply += `📦 جهة التوصيل/الناقل: ${order.carrier}\n🔍 رقم التتبع: ${order.tracking_number}\n📅 تاريخ الوصول المتوقع: ${formattedDate}\n`;
    } else {
      reply += `يتم تجهيز طلبك حالياً، والتاريخ المتوقع للاكتمال: ${formattedDate}.\n`;
    }
    if (order.service_type) {
      reply += `📋 نوع الخدمة: ${order.service_type}\n`;
    }
    reply += `\nنسعد بخدمتك دائماً. هل لديك أي استفسار آخر؟`;
  } else {
    reply = `Hello ${order.full_name || 'there'},\nYour service request/order **${order.order_number}** is currently **${statusText}**.\n\n`;
    if (order.carrier && order.tracking_number) {
      reply += `📦 Carrier: ${order.carrier}\n🔍 Tracking Number: ${order.tracking_number}\n📅 Estimated Delivery: ${formattedDate}\n`;
    } else {
      reply += `We are processing your request. Estimated completion: ${formattedDate}.\n`;
    }
    if (order.service_type) {
      reply += `📋 Service Type: ${order.service_type}\n`;
    }
    reply += `\nTotal: ${order.total_amount} ${order.currency}. Please let us know if you need any additional support!`;
  }

  return [{
    json: {
      status: 'success',
      intent_handled: 'order_lookup',
      order_found: true,
      order_data: order,
      reply: reply
    }
  }];
} else {
  const requestedNum = inputData.ai_output?.entities?.order_number || inputData.entities?.order_number || (inputData.customer_message || '').match(/(?:ord|srv)-\d+/i)?.[0] || (isAr ? 'الطلب المحدد' : 'your requested order');
  const notFoundReply = isAr
    ? `لم نتمكن من العثور على طلب أو معاملة برقم "${requestedNum}". يرجى التأكد من صحة رقم الطلب (مثال: SRV-1001 أو ORD-1001) أو إرسال رقم الهوية/الجوال المسجل.`
    : `I could not find an active service request or order matching "${requestedNum}". Please verify the reference number (e.g. SRV-1001 or ORD-1001) or provide your registered contact details.`;

  return [{
    json: {
      status: 'not_found',
      intent_handled: 'order_lookup',
      order_found: false,
      reply: notFoundReply
    }
  }];
}
